#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef unsigned long long ull;
typedef long double ld;
typedef pair<int, int> pii;
typedef vector<int> vi;
typedef vector<pii> vii;

const int MOD = 1000000007;
const int MOD2 = 1007681537;
const int INF = 1e9;
const ll LINF = 1e18;
const ld PI = acos((ld)-1);
const ld EPS = 1e-9;

inline ll gcd(ll a, ll b) { while (b) { ll t = a % b; a = b; b = t; } return a; }
inline ll lcm(ll a, ll b) { return a / gcd(a, b) * b; }
inline ll fpow(ll n, ll k, int p = MOD) { ll r = 1; for (; k; k >>= 1) { if (k & 1) r = r * n % p; n = n * n % p; } return r; }
template<class T> inline int chkmin(T& a, const T& val) { return val < a ? a = val, 1 : 0; }
template<class T> inline int chkmax(T& a, const T& val) { return a < val ? a = val, 1 : 0; }
inline ll isqrt(ll k) { ll r = sqrt(k) + 1; while (r * r > k) r--; return r; }
inline ll icbrt(ll k) { ll r = cbrt(k) + 1; while (r * r * r > k) r--; return r; }
inline void addmod(int& a, int val, int p = MOD) { a += val; if (a >= p) a -= p; }
inline void submod(int& a, int val, int p = MOD) { a -= val; if (a < 0) a += p; }
inline int mult(int a, int b, int p = MOD) { return (ll)a * b % p; }
inline int inv(int a, int p = MOD) { return fpow(a, p - 2, p); }
inline int sign(ld x) { return (x > EPS) - (x < -EPS); }

void transform(int a[], int n, int p, int invert) {
    for (int i = 1; i < n; i <<= 1) {
        for (int msk = 0; msk < n; ++msk) {
            if (msk & i) {
                int pmsk = msk ^ i;
                if (!invert) {
                    a[msk] = (a[msk] + a[pmsk]) % p;
                } else {
                    a[msk] = (a[msk] - a[pmsk] + p) % p;
                }
            }
        }
    }
}

vi pow_convol(vi a, int k, int p) {
    int n = a.size();
    if (k == 1) return a;
    if (k & 1) {
        vi r = pow_convol(a, k - 1, p);
        vi res(n, 0);
        for (int i = 0; i < n; ++i) {
            if (r[i] == 0) continue;
            for (int j = 0; j < n - i; ++j) {
                res[i + j] = (res[i + j] + (ll)r[i] * a[j]) % p;
            }
        }
        return res;
    } else {
        vi r = pow_convol(a, k >> 1, p);
        vi res(n, 0);
        for (int i = 0; i < n; ++i) {
            if (r[i] == 0) continue;
            for (int j = 0; j < n - i; ++j) {
                res[i + j] = (res[i + j] + (ll)r[i] * r[j]) % p;
            }
        }
        return res;
    }
}

vi subset_pow_convol(vi a, int k, int p) {
    static const int logn = 19;
    static vector<vector<int>> fa(logn, vector<int>(1 << logn, 0));
    static vector<vector<int>> fc(logn, vector<int>(1 << logn, 0));
    int n = a.size();
    while (n != (n & -n)) n += n & -n;
    vi res(n, 0);
    for (int i = 0; i < logn; ++i) {
        for (int j = 0; j < n; ++j) {
            if (__builtin_popcount(j) == i) {
                fa[i][j] = (j < (int)a.size()) ? a[j] : 0;
            } else {
                fa[i][j] = 0;
            }
            fc[i][j] = 0;
        }
        transform(fa[i].data(), n, p, 0);
    }
    for (int i = 0; i < n; ++i) {
        vi va(logn);
        for (int j = 0; j < logn; ++j) {
            va[j] = fa[j][i];
        }
        va = pow_convol(va, k, p);
        for (int j = 0; j < logn; ++j) {
            fc[j][i] = va[j];
        }
    }
    for (int i = 0; i < logn; ++i) {
        transform(fc[i].data(), n, p, 1);
        for (int j = 0; j < n; ++j) {
            if (__builtin_popcount(j) == i) {
                res[j] = fc[i][j];
            }
        }
    }
    return res;
}

const int maxn = 1000005;
int n, k, p;
int fac[maxn];
int ifac[maxn];
int f[maxn];

void solve() {
    cin >> n >> k >> p;
    int nn = n;
    for (int i = 0; i <= n; ++i) {
        if ((n & i) == i) {
            int t = 0;
            for (int j = 0; j < 20; ++j) {
                if ((n >> j) & 1) {
                    t = (t << 1) | ((i >> j) & 1);
                }
            }
            f[t] = i;
            nn = t;
        }
    }
    if (n & 1) {
        cout << fpow(k, n, p) << "\n";
        return;
    }
    fac[0] = 1;
    for (int i = 1; i < maxn; ++i) fac[i] = mult(fac[i - 1], i, p);
    for (int i = 0; i < maxn; ++i) ifac[i] = inv(fac[i], p);
    vi a(nn + 1, 0);
    for (int i = 0; i <= nn; ++i) a[i] = ifac[f[i]];
    int res = fpow(k, n, p);
    a = subset_pow_convol(a, k, p);
    submod(res, mult(a[nn], fac[n], p), p);
    cout << res << "\n";
}

int main() {
    int JUDGE_ONLINE = 1;
    if (fopen("in.txt", "r")) {
        JUDGE_ONLINE = 0;
        assert(freopen("in.txt", "r", stdin));
    } else {
        ios_base::sync_with_stdio(0), cin.tie(0);
    }
    solve();
    return 0;
}
