import java.io.*;
import java.util.*;

public class Main {
    static final int MOD = 1000000007;
    static final int MOD2 = 1007681537;
    static final int INF = (int)1e9;
    static final long LINF = (long)1e18;
    static final double PI = Math.acos(-1.0);
    static final double EPS = 1e-9;
    static final int MAXN = 1000005;
    static final int LOGN = 19;
    static final int MAXS = 1 << LOGN;

    static int[] fac = new int[MAXN];
    static int[] ifac = new int[MAXN];
    static int[] f = new int[MAXN];
    static int[][] fa = new int[LOGN][MAXS];
    static int[][] fc = new int[LOGN][MAXS];

    static long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    static long lcm(long a, long b) {
        return a / gcd(a, b) * b;
    }

    static long fpow(long n, long k, int p) {
        long r = 1;
        while (k > 0) {
            if ((k & 1) == 1) r = r * n % p;
            n = n * n % p;
            k >>= 1;
        }
        return r;
    }

    static int chkmin(int[] a, int val) {
        if (val < a[0]) {
            a[0] = val;
            return 1;
        }
        return 0;
    }

    static int chkmax(int[] a, int val) {
        if (a[0] < val) {
            a[0] = val;
            return 1;
        }
        return 0;
    }

    static long isqrt(long k) {
        long r = (long)Math.sqrt(k) + 1;
        while (r * r > k) r--;
        return r;
    }

    static long icbrt(long k) {
        long r = (long)Math.cbrt(k) + 1;
        while (r * r * r > k) r--;
        return r;
    }

    static void addmod(int[] a, int val, int p) {
        a[0] += val;
        if (a[0] >= p) a[0] -= p;
    }

    static void submod(int[] a, int val, int p) {
        a[0] -= val;
        if (a[0] < 0) a[0] += p;
    }

    static int mult(int a, int b, int p) {
        return (int)((long)a * b % p);
    }

    static int inv(int a, int p) {
        return (int)fpow(a, p - 2, p);
    }

    static int sign(double x) {
        if (x > EPS) return 1;
        if (x < -EPS) return -1;
        return 0;
    }

    static void transform(int[] a, int n, int p, int invert) {
        for (int i = 1; i < n; i <<= 1) {
            for (int msk = 0; msk < n; ++msk) {
                if ((msk & i) != 0) {
                    int pmsk = msk ^ i;
                    if (invert == 0) {
                        a[msk] = (a[msk] + a[pmsk]) % p;
                    } else {
                        a[msk] = (a[msk] - a[pmsk] + p) % p;
                    }
                }
            }
        }
    }

    static int[] powConvol(int[] a, int k, int p) {
        int n = a.length;
        if (k == 1) return a.clone();
        if ((k & 1) == 1) {
            int[] r = powConvol(a, k - 1, p);
            int[] res = new int[n];
            for (int i = 0; i < n; ++i) {
                if (r[i] == 0) continue;
                for (int j = 0; j < n - i; ++j) {
                    res[i + j] = (res[i + j] + (int)((long)r[i] * a[j] % p)) % p;
                }
            }
            return res;
        } else {
            int[] r = powConvol(a, k >> 1, p);
            int[] res = new int[n];
            for (int i = 0; i < n; ++i) {
                if (r[i] == 0) continue;
                for (int j = 0; j < n - i; ++j) {
                    res[i + j] = (res[i + j] + (int)((long)r[i] * r[j] % p)) % p;
                }
            }
            return res;
        }
    }

    static int[] subsetPowConvol(int[] a, int k, int p) {
        int n = a.length;
        while (n != (n & -n)) n += n & -n;
        int[] res = new int[n];
        for (int i = 0; i < LOGN; ++i) {
            for (int j = 0; j < n; ++j) {
                if (Integer.bitCount(j) == i) {
                    fa[i][j] = (j < a.length) ? a[j] : 0;
                } else {
                    fa[i][j] = 0;
                }
                fc[i][j] = 0;
            }
            transform(fa[i], n, p, 0);
        }
        for (int i = 0; i < n; ++i) {
            int[] va = new int[LOGN];
            for (int j = 0; j < LOGN; ++j) {
                va[j] = fa[j][i];
            }
            va = powConvol(va, k, p);
            for (int j = 0; j < LOGN; ++j) {
                fc[j][i] = va[j];
            }
        }
        for (int i = 0; i < LOGN; ++i) {
            transform(fc[i], n, p, 1);
            for (int j = 0; j < n; ++j) {
                if (Integer.bitCount(j) == i) {
                    res[j] = fc[i][j];
                }
            }
        }
        return res;
    }

    static void solve() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int p = Integer.parseInt(st.nextToken());

        int nn = n;
        for (int i = 0; i <= n; ++i) {
            if ((n & i) == i) {
                int t = 0;
                for (int j = 0; j < 20; ++j) {
                    if (((n >> j) & 1) == 1) {
                        t = (t << 1) | ((i >> j) & 1);
                    }
                }
                f[t] = i;
                nn = t;
            }
        }

        if ((n & 1) == 1) {
            System.out.println(fpow(k, n, p));
            return;
        }

        fac[0] = 1;
        for (int i = 1; i < MAXN; ++i) fac[i] = mult(fac[i - 1], i, p);
        for (int i = 0; i < MAXN; ++i) ifac[i] = inv(fac[i], p);

        int[] a = new int[nn + 1];
        for (int i = 0; i <= nn; ++i) a[i] = ifac[f[i]];

        int res = (int)fpow(k, n, p);
        int[] conv = subsetPowConvol(a, k, p);
        res = (res - mult(conv[nn], fac[n], p) + p) % p;
        System.out.println(res);
    }

    public static void main(String[] args) throws IOException {
        solve();
    }
}
